/** The tab's favicon says two things (#1736): the app runs through the Home Free relay, and
 *  something is unread (a bell notification, or an HQ reply).
 *
 *  It reads the SAME sources the top bar does (`notificationsStore`, `askUnreadStore`, and
 *  `homefree/relayStatus`), so it never polls on its own and never disagrees with the bell badge
 *  or the HQ dot. Each state is its own static file (generated by `scripts/brand.mjs`), under the
 *  build's base, so the relay build (`/connect/`) never asks the landing host's root for it and a
 *  state change is a URL change the browser repaints. It touches only the one `<link rel=icon>`
 *  and puts back the page's own icon when the app unmounts. */
import { useEffect, useSyncExternalStore } from "react";

import { useAskUnread } from "../components/ask/askUnreadStore";
import { useNotificationsUnread } from "../components/pulse/notificationsStore";
import { getRelaySnapshot, subscribeRelay } from "../homefree/relayStatus";

/** The favicon file for a state, under `base` (the build's `import.meta.env.BASE_URL`). */
export function faviconHref(relay: boolean, unread: boolean, base: string = import.meta.env.BASE_URL): string {
  return `${base}favicon${relay ? "-relay" : ""}${unread ? "-unread" : ""}.svg`;
}

/** The page's icon link, made if the page has none. */
function iconLink(): HTMLLinkElement {
  const found = document.head.querySelector<HTMLLinkElement>('link[rel~="icon"]');
  if (found) return found;
  const link = document.createElement("link");
  link.rel = "icon";
  link.type = "image/svg+xml";
  document.head.appendChild(link);
  return link;
}

const relayLinked = () => getRelaySnapshot() !== null;

export function useFavicon(): void {
  const relay = useSyncExternalStore(subscribeRelay, relayLinked, () => false);
  const bell = useNotificationsUnread();
  const ask = useAskUnread();
  const href = faviconHref(relay, bell || ask);

  // The page's own icon, put back when the app goes (the relay shell outlives the app it mounts).
  useEffect(() => {
    const link = iconLink();
    const original = link.getAttribute("href");
    return () => {
      if (original === null) link.removeAttribute("href");
      else link.setAttribute("href", original);
    };
  }, []);

  useEffect(() => {
    const link = iconLink();
    if (link.getAttribute("href") !== href) link.setAttribute("href", href);
  }, [href]);
}
